@login_required
@transaction.atomic
def employee_invite(request):
    require_role(request.user, HR_ADMIN)
    form = InviteEmployeeForm(request.POST or None)
    if request.method == "POST" and form.is_valid():
        password = get_random_string(16)
        user = User.objects.create_user(
            username=form.cleaned_data["username"],
            email=form.cleaned_data["email"],
            password=password,
            first_name=form.cleaned_data["first_name"],
            last_name=form.cleaned_data["last_name"],
        )

def clean_document(self):
        doc = self.cleaned_data["document"]
        if doc.size > 10 * 1024 * 1024:
            raise ValidationError("Files must be 10MB or smaller.")
        return doc

role = role_for(request.user)
    qs = CompensationRequest.objects.select_related("employee__user", "requested_by")
    if role == MANAGER:
        qs = qs.filter(employee__manager=request.user.employee_profile)
    elif role == EMPLOYEE:
        qs = qs.filter(employee=request.user.employee_profile)
    elif role == PAYROLL:
        qs = qs.filter(status__in=["hr_approved", "effective"])
